"""reports/RESULTS.md, generated from reports/results.json by `devprod run`. Do not edit by hand."""

from __future__ import annotations

from typing import Any


def _f(x: Any, unit: str = "") -> str:
    if x is None:
        return "–"
    if isinstance(x, float):
        x = round(x, 3) if abs(x) < 10 else round(x, 1) if abs(x) < 100 else round(x)
    if isinstance(x, (int, float)) and abs(x) >= 10000:
        return f"{x:,.0f}{unit}"
    return f"{x}{unit}"


def _row(name: str, b: Any, c: Any, unit: str = "") -> str:
    return f"| {name} | {_f(b, unit)} | {_f(c, unit)} |"


def markdown(r: dict[str, Any]) -> str:
    b, c = r["worlds"]["baseline"], r["worlds"]["control-plane"]
    bo, co = b["observed"], c["observed"]
    bt, ct = b["truth"], c["truth"]
    lines = [
        "# Results",
        "",
        "Generated by `devprod run` from `reports/results.json`. Ten simulated weeks of a 42-engineer monorepo "
        "(25 modules, Python and TypeScript) and 260 customer AWS accounts. *Baseline* is a good ordinary setup: "
        "path-filtered workflows, one job per module, a fixed runner fleet, people triaging CI failures, "
        "staging then everyone. *Control plane* is this repository. Both worlds share their randomness by key, "
        "so the same test flakes on the same commit and the same change breaks the same thing.",
        "",
        "## Release gate",
        "",
        "| Check | Value | Bound | |",
        "|---|---|---|---|",
    ]
    for g in r["gate"]:
        lines.append(
            f"| {g['name']} | {_f(g['value'])} | {g['op']} {_f(g['bound'])} | {'pass' if g['passed'] else '**FAIL**'} |"
        )
    lines += [
        "",
        "## CI, as the dashboard sees it (observed)",
        "",
        "| Measure | Baseline | Control plane |",
        "|---|---|---|",
        _row(
            "PR lead time p50 / p90 (h)",
            f"{bo['ci']['pr_lead_time_hours']['p50']} / {bo['ci']['pr_lead_time_hours']['p90']}",
            f"{co['ci']['pr_lead_time_hours']['p50']} / {co['ci']['pr_lead_time_hours']['p90']}",
        ),
        _row(
            "CI wall time p50 / p95 (min)",
            f"{bo['ci']['ci_wall_minutes']['p50']} / {bo['ci']['ci_wall_minutes']['p95']}",
            f"{co['ci']['ci_wall_minutes']['p50']} / {co['ci']['ci_wall_minutes']['p95']}",
        ),
        _row(
            "Push to green p50 / p95 (min)",
            f"{bo['ci']['push_to_green_minutes']['p50']} / {bo['ci']['push_to_green_minutes']['p95']}",
            f"{co['ci']['push_to_green_minutes']['p50']} / {co['ci']['push_to_green_minutes']['p95']}",
        ),
        _row(
            "Runner queue mean / p95 (min)",
            f"{bo['ci']['queue_minutes']['mean']} / {bo['ci']['queue_minutes']['p95']}",
            f"{co['ci']['queue_minutes']['mean']} / {co['ci']['queue_minutes']['p95']}",
        ),
        _row("Jobs", bo["ci"]["jobs"], co["ci"]["jobs"]),
        _row("Job minutes", bo["ci"]["job_minutes"], co["ci"]["job_minutes"]),
        _row("Runner minutes billed", bo["ci"]["runner_minutes"], co["ci"]["runner_minutes"]),
        _row("Peak runners", bo["ci"]["peak_runners"], co["ci"]["peak_runners"]),
        _row("Cache hit share", bo["ci"]["cache_hit_share"], co["ci"]["cache_hit_share"]),
        _row("Failed first runs", bo["ci"]["failed_push_share"], co["ci"]["failed_push_share"]),
        _row(
            "Failed then passed on the same commit",
            bo["ci"]["failed_then_passed_same_commit"],
            co["ci"]["failed_then_passed_same_commit"],
        ),
        _row("PRs per engineer-day", bo["ci"]["prs_per_engineer_day"], co["ci"]["prs_per_engineer_day"]),
        _row("Quarantined tests", bo["ci"]["quarantined_tests"], co["ci"]["quarantined_tests"]),
        "",
        "## CI, against the truth",
        "",
        "| Measure | Baseline | Control plane |",
        "|---|---|---|",
        _row("Regressions in changes", bt["ci"]["regressions"], ct["ci"]["regressions"]),
        _row("... caught by CI", bt["ci"]["regressions_caught"], ct["ci"]["regressions_caught"]),
        _row("... reached main", bt["ci"]["regressions_escaped"], ct["ci"]["regressions_escaped"]),
        _row(
            "... hidden by quarantine",
            bt["ci"]["regressions_hidden_by_quarantine"],
            ct["ci"]["regressions_hidden_by_quarantine"],
        ),
        _row("Human minutes on CI failures", bt["ci"]["human_minutes"], ct["ci"]["human_minutes"]),
        _row("Agent spend (USD)", b["summary"]["agent_usd"], c["summary"]["agent_usd"]),
    ]
    a = ct["ci"].get("agent")
    if a:
        lines += [
            "",
            f"Triage agent: {a['judged']} failures judged, accuracy {a['accuracy']}, regression precision "
            f"{a['regression_precision']}, recall {a['regression_recall']}.",
            "",
            "| Truth \\ agent | " + " | ".join(a["confusion"]) + " |",
            "|---" * (len(a["confusion"]) + 1) + "|",
        ]
        for k, row in a["confusion"].items():
            lines.append(f"| {k} | " + " | ".join(str(row.get(x, 0)) for x in a["confusion"]) + " |")
    fd = ct["ci"]["flake_detector"]
    lines += [
        "",
        f"Flaky-test detector: {fd['quarantined']} quarantined, precision {fd['precision']}; it found "
        f"{fd['recall_of_seen_failing']} of the {fd['truly_flaky_seen_failing']} truly flaky tests that failed at "
        f"least once, and {fd['recall_of_flake_rate_ge_2pct']} of those flaking at 2% or more. "
        f"Wrongly quarantined: {', '.join(fd['wrongly_quarantined']) or 'none'}.",
        "",
        "## Delivery to customer accounts",
        "",
        "| Measure | Baseline | Control plane |",
        "|---|---|---|",
        _row(
            "Releases cut / rollouts started",
            f"{bt['deploys']['releases']} / {bt['deploys']['rollouts']}",
            f"{ct['deploys']['releases']} / {ct['deploys']['rollouts']}",
        ),
        _row("Rollouts of a bad release", bt["deploys"]["bad_rollouts"], ct["deploys"]["bad_rollouts"]),
        _row("... stopped by a gate", bt["deploys"]["stopped_by_gate"], ct["deploys"]["stopped_by_gate"]),
        _row(
            "... rolled back by a person",
            bt["deploys"]["rolled_back_by_person"],
            ct["deploys"]["rolled_back_by_person"],
        ),
        _row("False rollbacks (good release)", bt["deploys"]["false_rollbacks"], ct["deploys"]["false_rollbacks"]),
        _row(
            "Customer accounts that ran a bad release",
            bt["deploys"]["customer_accounts_hit"],
            ct["deploys"]["customer_accounts_hit"],
        ),
        _row("Extra failed decisions (truth)", bt["deploys"]["bad_decisions"], ct["deploys"]["bad_decisions"]),
        _row(
            "Deploys per working day (DORA)",
            bo["delivery"]["deploys_per_working_day"],
            co["delivery"]["deploys_per_working_day"],
        ),
        _row(
            "Change failure rate (DORA)", bo["delivery"]["change_failure_rate"], co["delivery"]["change_failure_rate"]
        ),
        _row(
            "Lead time for changes p50 / p90 (h)",
            f"{bo['delivery']['lead_time_for_changes_hours']['p50']} / {bo['delivery']['lead_time_for_changes_hours']['p90']}",
            f"{co['delivery']['lead_time_for_changes_hours']['p50']} / {co['delivery']['lead_time_for_changes_hours']['p90']}",
        ),
        _row(
            "Time to restore p50 (min)",
            bo["delivery"]["time_to_restore_minutes"]["p50"],
            co["delivery"]["time_to_restore_minutes"]["p50"],
        ),
    ]
    if r.get("ablations"):
        lines += [
            "",
            "## Ablation: the usual canary",
            "",
            "The same control-plane world, deployed with a pooled gate and a canary of the quietest starter "
            "accounts (`control-plane-pooled` in config/deploy.yaml).",
            "",
            "| Deploy settings | Stopped by gate | Rolled back by a person | False rollbacks | Accounts hit | "
            "Extra failed decisions |",
            "|---|---|---|---|---|---|",
            f"| control-plane (stratified, per tier) | {ct['deploys']['stopped_by_gate']} | "
            f"{ct['deploys']['rolled_back_by_person']} | {ct['deploys']['false_rollbacks']} | "
            f"{ct['deploys']['customer_accounts_hit']} | {_f(ct['deploys']['bad_decisions'])} |",
        ]
        for name, s in r["ablations"].items():
            lines.append(
                f"| {name} | {s['stopped_by_gate']} | {s['rolled_back_by_person']} | {s['false_rollbacks']} | "
                f"{s['customer_accounts_hit']} | {_f(s['bad_decisions'])} |"
            )
    if r.get("heldout"):
        lines += ["", "## Held-out failures", "", r["heldout"]]
    return "\n".join(lines) + "\n"
